USE cdoprints_db;

SET FOREIGN_KEY_CHECKS = 1;

START TRANSACTION;

SET @b_users = (SELECT IFNULL(MAX(user_id), 0) FROM users);
SET @b_cust = (SELECT IFNULL(MAX(customer_id), 0) FROM customers);
SET @b_ord = (SELECT IFNULL(MAX(order_id), 0) FROM printing_orders);
SET @b_dv = (SELECT IFNULL(MAX(design_version_id), 0) FROM design_versions);
SET @b_prec = (SELECT IFNULL(MAX(production_record_id), 0) FROM production_records);
































































































































































COMMIT;
